package br.pucminas.iceibank.controller; import br.pucminas.iceibank.dto.TransferenciaRequest; import br.pucminas.iceibank.service.TransferenciaService; import org.springframework.web.bind.annotation.*; import java.util.Map; @RestController public class TransferenciaController {private final TransferenciaService service; public TransferenciaController(TransferenciaService s){service=s;} @PostMapping("/transferencias") public Map<String,Object> transferir(@RequestBody TransferenciaRequest r){return service.transferir(r.idOrigem(),r.idDestino(),r.valor());}}
